import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

export type Message = { role: "user" | "assistant"; text: string };

/** The subset of WebSocket the conversation uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export class Conversation {
  private readonly turns: Anthropic.MessageParam[];
  private pending: { requestId: string; blocks: string[] } | undefined;
  private settle: (() => void) | undefined;
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | undefined;

  constructor(
    socket: Socket,
    opts: {
      system?: string;
      initialTurns?: Anthropic.MessageParam[];
      seed?: string;
    } = {},
  ) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.seed = opts.seed;
    this.turns = opts.seed
      ? [{ role: "user", content: opts.seed }]
      : [...(opts.initialTurns ?? [])];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** Committed turns plus the one currently streaming. */
  get messages(): ReadonlyArray<Message> {
    const turns = this.seed ? this.turns.slice(1) : this.turns;
    const committed = turns.map(
      (turn): Message => ({
        role: turn.role === "assistant" ? "assistant" : "user",
        text: textOf(turn),
      }),
    );
    const streaming = this.pending?.blocks.join("");
    if (streaming) committed.push({ role: "assistant", text: streaming });
    return committed;
  }

  get inFlight(): boolean {
    return this.pending !== undefined;
  }

  send(text: string): Promise<void> {
    if (this.pending) return Promise.resolve();
    this.turns.push({ role: "user", content: text });
    return this.request();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<void> {
    if (this.pending || this.turns.length === 0) return Promise.resolve();
    return this.request();
  }

  private request(): Promise<void> {
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [] };
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<void>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start":
        pending.blocks[event.index] = blockStartText(event.content_block);
        break;
      case "content_block_delta":
        pending.blocks[event.index] =
          (pending.blocks[event.index] ?? "") + deltaText(event.delta);
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
      case "message_delta":
      case "content_block_stop":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    const text = pending.blocks.join("");
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (text.length > 0) this.turns.push({ role: "assistant", content: text });
    this.settle?.();
    this.settle = undefined;
  }
}

function textOf(turn: Anthropic.MessageParam): string {
  if (typeof turn.content === "string") return turn.content;
  return turn.content
    .map((block) => (block.type === "text" ? block.text : ""))
    .join("");
}

/** This prototype has no tools and no thinking, so the non-text variants are
 * listed to be explicitly ignored rather than silently dropped - when we add
 * them, this is where they surface. */
function blockStartText(block: Anthropic.ContentBlock): string {
  switch (block.type) {
    case "text":
      return block.text;
    default:
      console.warn("unhandled content block", block);
      return "";
  }
}

function deltaText(delta: Anthropic.RawContentBlockDelta): string {
  switch (delta.type) {
    case "text_delta":
      return delta.text;
    default:
      console.warn("unhandled content block delta", delta);
      return "";
  }
}

import { type Anchor, anchorText } from "./selection.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript and point at a passage they picked out.",
  "Answer about that passage specifically, in plain language, and assume the",
  "user has not followed the reasoning that produced it. Be concise, and do",
  "not restate the whole transcript back to them.",
].join(" ");

/** The single synthetic user turn seeding a learning thread. `seed` is the
 * parent's own seed and is emitted verbatim - wrapping or re-labelling it
 * would nest the framing one layer deeper at every level. */
export function seedTurn(
  seed: string | undefined,
  messages: ReadonlyArray<{ role: "user" | "assistant"; text: string }>,
  anchor: Anchor,
  action: Action,
): string {
  const visible = messages.slice(0, anchor.end.msg + 1);
  const sections = [];
  if (seed) sections.push(seed);
  sections.push(transcript(visible));
  sections.push(
    `The user then selected: "${anchorText(anchor, visible)}"\n${question(action)}`,
  );
  return sections.join("\n\n");
}

function transcript(
  messages: ReadonlyArray<{ role: "user" | "assistant"; text: string }>,
): string {
  return messages
    .map((m) => `${m.role === "user" ? "User" : "Assistant"}: ${m.text}`)
    .join("\n\n");
}

function question(action: Action): string {
  switch (action.type) {
    case "explain":
      return "They said they don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.";
    case "query":
      return `They asked: ${action.text}`;
  }
}

/** Declared here rather than in threads.ts because an anchor is meaningless
 * without one, and threads.ts will import this module. */
export type ThreadId = string & { readonly __brand: "ThreadId" };

/** A selection over the transcript, stored as character offsets into message
 * text rather than as a live DOM Range: the browser's Range dies the moment the
 * user clicks the learning pane, and the transcript is append-only, so offsets
 * stay valid while a message is still streaming.
 *
 * `msg` is an absolute index into the owning thread's turns, `offset` a
 * character offset into that turn's text. */
export type Point = { msg: number; offset: number };
/** `start` precedes `end` in document order; `thread` is the thread whose
 * transcript the range indexes, i.e. the parent of whatever it opens. */
export type Anchor = { thread: ThreadId; start: Point; end: Point };

/** A committed highlight: the passage, plus the thread it opens. The opened
 * thread's id cannot live on the anchor, because `anchor.thread` already names
 * the other end of the edge - the parent. */
export type Mark = { thread: ThreadId; anchor: Anchor };

/** A run of one message's text: plain, a committed mark, or the live selection
 * the user has just dragged and not yet acted on. */
export type Segment = {
  start: number;
  end: number;
  /** The thread this run opens, or null for plain text and the live range. */
  thread: ThreadId | null;
  live: boolean;
};

/** True when `live` intersects any committed mark, which makes it unusable:
 * a passage owned by two threads has no honest meaning as an edge in the tree. */
export function overlaps(marks: ReadonlyArray<Mark>, live: Anchor): boolean {
  return marks.some(
    (m) => before(m.anchor.start, live.end) && before(live.start, m.anchor.end),
  );
}

function before(a: Point, b: Point): boolean {
  return a.msg !== b.msg ? a.msg < b.msg : a.offset < b.offset;
}

/** Splits message `i` into plain, marked and live runs, left to right.
 * `marks` are pairwise disjoint; `live` may overlap them, and wins where it
 * does, so the user still sees what they dragged. */
export function segments(
  marks: ReadonlyArray<Mark>,
  live: Anchor | null,
  i: number,
  length: number,
): Segment[] {
  const liveClip = clipToMessage(live, i, length);
  const runs: Segment[] = [];
  for (const mark of marks) {
    const clip = clipToMessage(mark.anchor, i, length);
    if (!clip) continue;
    for (const part of subtract(clip, liveClip)) {
      runs.push({ ...part, thread: mark.thread, live: false });
    }
  }
  if (liveClip) runs.push({ ...liveClip, thread: null, live: true });
  runs.sort((a, b) => a.start - b.start);

  const out: Segment[] = [];
  let at = 0;
  for (const run of runs) {
    if (run.start > at) {
      out.push({ start: at, end: run.start, thread: null, live: false });
    }
    out.push(run);
    at = run.end;
  }
  if (at < length) {
    out.push({ start: at, end: length, thread: null, live: false });
  }
  return out;
}

type Run = { start: number; end: number };

function subtract(run: Run, hole: Run | null): Run[] {
  if (!hole || hole.end <= run.start || hole.start >= run.end) return [run];
  const out: Run[] = [];
  if (run.start < hole.start) out.push({ start: run.start, end: hole.start });
  if (run.end > hole.end) out.push({ start: hole.end, end: run.end });
  return out;
}

/** The portion of `anchor` falling inside message `i`, or null. */
function clipToMessage(
  anchor: Anchor | null,
  i: number,
  length: number,
): { start: number; end: number } | null {
  if (!anchor) return null;
  if (i < anchor.start.msg || i > anchor.end.msg) return null;
  const start = i === anchor.start.msg ? anchor.start.offset : 0;
  const end = i === anchor.end.msg ? anchor.end.offset : length;
  return end > start ? { start, end } : null;
}

export function anchorText(
  anchor: Anchor,
  messages: ReadonlyArray<{ text: string }>,
): string {
  const parts: string[] = [];
  for (let i = anchor.start.msg; i <= anchor.end.msg; i++) {
    const clip = clipToMessage(anchor, i, messages[i]?.text.length ?? 0);
    if (clip) parts.push(messages[i].text.slice(clip.start, clip.end));
  }
  return parts.join("\n\n");
}

import type { Message } from "./conversation.ts";
import {
  type Action,
  type Msg as LearningMsg,
  LearningPane,
  type State as LearningState,
} from "./learning.ts";
import {
  type Anchor,
  anchorText,
  type Mark,
  overlaps,
  type Point,
  type Segment,
  segments,
  type ThreadId,
} from "./selection.ts";
import {
  Binder,
  cls,
  mountStyle,
  type Ref,
  ref,
  sanitize,
  show,
  showKeyed,
  type View,
} from "./vamp.ts";

export type Mode = "task" | "learning";

export type State = {
  messages: ReadonlyArray<Message>;
  inFlight: boolean;
  draft: string;
  mode: Mode;
  /** The thread whose transcript this pane shows; the live selection is over it. */
  thread: ThreadId;
  /** Committed highlights over this transcript. */
  marks: ReadonlyArray<Mark>;
  /** The mark whose thread the right pane is showing, drawn emphasized. */
  activeMark: ThreadId | null;
  anchor: Anchor | null;
  query: string;
  pending: Action | null;
};

export type Msg =
  | { type: "DRAFT_CHANGED"; draft: string }
  | { type: "SUBMIT" }
  | { type: "MODE_TOGGLED" }
  | { type: "SELECTION_CHANGED"; anchor: Anchor | null }
  | { type: "MARK_CLICKED"; thread: ThreadId }
  | { type: "LEARNING_MSG"; msg: LearningMsg };

const appClass = cls("app");
const transcriptClass = cls("transcript");
const messageClass = cls("message");
const roleClass = cls("role");
const composerClass = cls("composer");
const paneClass = cls("pane");
const toggleClass = cls("toggle");
const markClass = cls("mark");
const textClass = cls("text");

mountStyle(`
.${appClass} {
  font-family: system-ui, sans-serif;
  max-width: 44rem;
  margin: 0 auto;
  padding: 1rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 1rem 2rem;
  align-items: start;
}
.${appClass}[data-mode="learning"] {
  max-width: 88rem;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.${paneClass} {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
}
.${toggleClass} {
  position: fixed;
  top: 4.5rem;
  right: 1rem;
  z-index: 10;
  font: inherit;
  padding: 0.4rem 0.8rem;
  border-radius: 999px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
  cursor: pointer;
}
.${markClass} {
  border-radius: 2px;
}
.${markClass}[data-live="true"] {
  background: #cfe3ff;
}
.${markClass}[data-mark] {
  background: #ffe8a3;
  cursor: pointer;
}
.${markClass}[data-mark][data-active="true"] {
  background: #ffcf4d;
  box-shadow: 0 0 0 1px #b8860b;
}
.${transcriptClass} {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.${messageClass} {
  white-space: pre-wrap;
  line-height: 1.5;
}
.${messageClass}[data-role="user"] {
  background: rgba(0, 0, 0, 0.05);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
}
.${roleClass} {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.6;
}
.${composerClass} {
  display: flex;
  gap: 0.5rem;
}
.${composerClass} textarea {
  flex: 1;
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
`);

type SegmentState = {
  text: string;
  /** The thread this run opens; null for plain text and the live selection. */
  thread: ThreadId | null;
  live: boolean;
  active: boolean;
};

type SegmentMsg = { type: "CLICKED"; thread: ThreadId };

/** One run of a message's text: plain, a committed mark, or the live selection.
 * A span rather than a <mark> so all three share one element and bindList can
 * reconcile them without remounting. */
class SegmentView implements View<SegmentState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<SegmentState>;
  private current: SegmentState;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: SegmentState,
  ) {
    const textRef = ref("segment");
    container.innerHTML = sanitize`<span data-ref="${textRef}"></span>`;
    this.container = container;
    this.current = initial;
    this.b = new Binder(container, initial);
    container.addEventListener("click", () => {
      const thread = this.current.thread;
      if (thread) dispatch({ type: "CLICKED", thread });
    });
    this.b.bindClass(container, (s) => (s.thread || s.live ? markClass : ""));
    this.b.bindContainerAttr("data-mark", (s) => s.thread ?? undefined);
    this.b.bindContainerAttr("data-live", (s) => (s.live ? "true" : undefined));
    this.b.bindContainerAttr("data-active", (s) =>
      s.active ? "true" : undefined,
    );
    this.b.bindText(textRef, (s) => s.text);
  }

  sync(state: SegmentState): void {
    this.current = state;
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

type MessageState = {
  message: Message;
  segments: ReadonlyArray<Segment>;
  active: ThreadId | null;
};

class MessageView implements View<MessageState, SegmentMsg> {
  container: HTMLElement;
  private b: Binder<MessageState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: SegmentMsg) => void,
    initial: MessageState,
  ) {
    const roleRef = ref("role");
    const textRef = ref("text");
    container.className = messageClass;
    container.innerHTML = sanitize`
      <span class="${roleClass}" data-ref="${roleRef}"></span>
      <span class="${textClass}" data-ref="${textRef}"></span>
    `;
    this.container = container;
    this.b = new Binder(container, initial);
    this.b.bindText(roleRef, (s) => s.message.role);
    // Keyed by start offset: the transcript is append-only, so a run keeps its
    // start while the message grows and while marks are added after it.
    this.b.bindList(textRef, "span", (s) =>
      s.segments.map((seg) =>
        showKeyed(
          String(seg.start),
          SegmentView,
          {
            text: s.message.text.slice(seg.start, seg.end),
            thread: seg.thread,
            live: seg.live,
            active: seg.thread !== null && seg.thread === s.active,
          },
          {},
          dispatch,
        ),
      ),
    );
    this.b.bindContainerAttr("data-role", (s) => s.message.role);
  }

  sync(state: MessageState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class AppView implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;
  /** The latest state, for event handlers that need it outside a binding. */
  private current: State;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const transcriptRef: Ref = ref("transcript");
    const inputRef: Ref = ref("input");
    const sendRef: Ref = ref("send");
    const toggleRef: Ref = ref("toggle");
    const composerRef: Ref = ref("composer");
    const learningRef: Ref = ref("learning");

    container.className = appClass;
    container.innerHTML = sanitize`
      <button type="button" class="${toggleClass}" data-ref="${toggleRef}"></button>
      <div class="${paneClass}">
        <ul class="${transcriptClass}" data-ref="${transcriptRef}"></ul>
        <div class="${composerClass}" data-ref="${composerRef}">
          <textarea data-ref="${inputRef}" rows="2" placeholder="Ask something…"></textarea>
          <button type="button" data-ref="${sendRef}">Send</button>
        </div>
      </div>
      <div data-ref="${learningRef}"></div>
    `;
    this.container = container;
    this.current = initialState;
    this.b = new Binder(container, initialState);

    const input = this.b.ref<HTMLTextAreaElement>(inputRef);
    input.addEventListener("input", () => {
      dispatch({ type: "DRAFT_CHANGED", draft: input.value });
    });
    input.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        dispatch({ type: "SUBMIT" });
      }
    });
    this.b
      .ref(sendRef)
      .addEventListener("click", () => dispatch({ type: "SUBMIT" }));
    this.b
      .ref(toggleRef)
      .addEventListener("click", () => dispatch({ type: "MODE_TOGGLED" }));

    // Capture on mouseup/keyup rather than `selectionchange`: the browser
    // collapses the selection as soon as the user clicks the learning pane,
    // which is exactly when we need the anchor to survive.
    const transcript = this.b.ref(transcriptRef);
    const capture = () => {
      const anchor = readAnchor(transcript, this.current.thread);
      if (anchor !== undefined) dispatch({ type: "SELECTION_CHANGED", anchor });
    };
    transcript.addEventListener("mouseup", capture);
    transcript.addEventListener("keyup", capture);

    // The transcript is append-only and never reorders, so the position of a
    // message is a stable identity.
    this.b.bindList(transcriptRef, "li", (s) =>
      s.messages.map((message, i) =>
        showKeyed(
          String(i),
          MessageView,
          {
            message,
            segments: segments(s.marks, s.anchor, i, message.text.length),
            active: s.activeMark,
          },
          {},
          (msg: SegmentMsg) =>
            dispatch({ type: "MARK_CLICKED", thread: msg.thread }),
        ),
      ),
    );
    this.b.bindContainerAttr("data-mode", (s) => s.mode);
    this.b.bindText(toggleRef, (s) =>
      s.mode === "task" ? "Switch to learning mode" : "Back to task mode",
    );
    this.b.bindVisible(composerRef, (s) => s.mode === "task");
    this.b.bindSlot(learningRef, (s) => {
      if (s.mode !== "learning") return undefined;
      const learningState: LearningState = {
        selection: paneSelection(s),
        overlapping: s.anchor !== null && overlaps(s.marks, s.anchor),
        query: s.query,
        pending: s.pending,
      };
      // bindSlot hands this straight to the child as its dispatch, so it must
      // dispatch rather than return a wrapped message.
      return show(LearningPane, learningState, {}, (msg: LearningMsg) =>
        dispatch({ type: "LEARNING_MSG", msg }),
      );
    });
    this.b.bindValue(inputRef, (s) => s.draft);
    this.b.bindDisabled(inputRef, (s) => s.inFlight);
    this.b.bindDisabled(sendRef, (s) => s.inFlight || s.draft.trim() === "");
  }

  sync(state: State): void {
    this.current = state;
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

/** The passage the right pane is about: the live selection, or - once one has
 * been committed - the mark whose thread is active. */
function paneSelection(s: State): string | null {
  if (s.anchor) return anchorText(s.anchor, s.messages);
  const active = s.marks.find((m) => m.thread === s.activeMark);
  return active ? anchorText(active.anchor, s.messages) : null;
}
/** Reads the live browser selection as an Anchor. Returns `undefined` when the
 * selection has nothing to do with the transcript, which must not clobber a
 * previously captured anchor. */
function readAnchor(
  transcript: HTMLElement,
  thread: ThreadId,
): Anchor | null | undefined {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return undefined;
  const range = selection.getRangeAt(0);
  const start = resolvePoint(
    transcript,
    range.startContainer,
    range.startOffset,
  );
  const end = resolvePoint(transcript, range.endContainer, range.endOffset);
  if (!start || !end) return undefined;
  if (start.msg === end.msg && start.offset === end.offset) return null;
  return { thread, start, end };
}

function resolvePoint(
  transcript: HTMLElement,
  node: Node,
  offset: number,
): Point | null {
  const el =
    node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
  const textEl = el?.closest(`.${textClass}`);
  if (!textEl || !transcript.contains(textEl)) return null;
  const li = textEl.closest("li");
  if (!li) return null;
  const msg = Array.prototype.indexOf.call(transcript.children, li);
  if (msg < 0) return null;

  // The message text is split across pre/mark/post spans, so a node-local
  // offset is not a message offset; measure the text preceding the point.
  const prefix = document.createRange();
  prefix.setStart(textEl, 0);
  prefix.setEnd(node, offset);
  return { msg, offset: prefix.toString().length };
}

import { Binder, cls, mountStyle, ref, sanitize, type View } from "./vamp.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

export type State = {
  /** The text the user highlighted, or null when nothing is selected. */
  selection: string | null;
  /** The live selection intersects a committed mark, so no action is offered. */
  overlapping: boolean;
  query: string;
  pending: Action | null;
};

export type Msg =
  | { type: "ACTION"; action: Action }
  | { type: "QUERY_CHANGED"; query: string };

const paneClass = cls("learning-pane");
const emptyClass = cls("learning-empty");
const quoteClass = cls("learning-quote");
const actionsClass = cls("learning-actions");
const pendingClass = cls("learning-pending");
const warnClass = cls("learning-warn");

mountStyle(`
.${paneClass} {
  position: sticky;
  top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${emptyClass} {
  opacity: 0.5;
  font-style: italic;
}
.${warnClass} {
  font-style: italic;
  color: #a35200;
}
.${quoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  padding-left: 0.75rem;
  max-height: 12rem;
  overflow-y: auto;
  font-size: 0.9rem;
}
.${actionsClass} {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
  text-align: left;
  padding: 0.5rem 0.75rem;
}
.${actionsClass} textarea {
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
.${pendingClass} {
  font-size: 0.85rem;
  opacity: 0.6;
}
`);

export class LearningPane implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const emptyRef = ref("empty");
    const bodyRef = ref("body");
    const quoteRef = ref("quote");
    const explainRef = ref("explain");
    const quizRef = ref("quiz");
    const queryRef = ref("query");
    const pendingRef = ref("pending");
    const warnRef = ref("warn");

    container.className = paneClass;
    container.innerHTML = sanitize`
      <p class="${emptyClass}" data-ref="${emptyRef}">Select some text to get started.</p>
      <p class="${warnClass}" data-ref="${warnRef}">Select a non-overlapping section.</p>
      <div class="${actionsClass}" data-ref="${bodyRef}">
        <blockquote class="${quoteClass}" data-ref="${quoteRef}"></blockquote>
        <button type="button" data-ref="${explainRef}">I don't understand this.</button>
        <button type="button" data-ref="${quizRef}">Quiz me on this.</button>
        <textarea data-ref="${queryRef}" rows="2" placeholder="Ask your own question…"></textarea>
        <span class="${pendingClass}" data-ref="${pendingRef}"></span>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );

    const query = this.b.ref<HTMLTextAreaElement>(queryRef);
    query.addEventListener("input", () => {
      dispatch({ type: "QUERY_CHANGED", query: query.value });
    });
    query.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      const text = query.value.trim();
      if (text === "") return;
      dispatch({ type: "ACTION", action: { type: "query", text } });
    });

    this.b.bindVisible(emptyRef, (s) => s.selection === null && !s.overlapping);
    this.b.bindVisible(warnRef, (s) => s.overlapping);
    this.b.bindVisible(bodyRef, (s) => s.selection !== null && !s.overlapping);
    this.b.bindText(quoteRef, (s) => s.selection ?? "");
    this.b.bindValue(queryRef, (s) => s.query);
    this.b.bindText(pendingRef, (s) =>
      s.pending === null ? "" : `${describe(s.pending)} — not wired up yet.`,
    );
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

function describe(action: Action): string {
  switch (action.type) {
    case "explain":
      return "Explain this";
    case "quiz":
      return "Quiz me";
    case "query":
      return action.text;
  }
}

import { Conversation } from "../conversation.ts";
import type { Action } from "../prompt.ts";
import { selectedSample } from "../samples/index.ts";
import type { Mark, ThreadId } from "../selection.ts";
import { overlaps } from "../selection.ts";
import { AppView, type Msg, type State } from "../view.ts";

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the plain task-mode transcript. The review affordances get
 * layered on top of this one. */
export function mount(container: HTMLElement): void {
  const conversation = new Conversation(connect(), {
    initialTurns: selectedSample()?.turns,
  });
  // Stage 3 replaces this with a ThreadTree; for now a committed mark is just
  // a passage plus the action taken on it, and the "thread" it opens is a
  // placeholder id that nothing streams into yet.
  const commits: Array<Mark & { action: Action }> = [];
  const root = "root" as ThreadId;

  const state: State = {
    messages: conversation.messages,
    inFlight: false,
    draft: "",
    mode: "task",
    thread: root,
    marks: commits,
    activeMark: null,
    anchor: null,
    query: "",
    pending: null,
  };

  function update(state: State, msg: Msg): void {
    switch (msg.type) {
      case "DRAFT_CHANGED":
        state.draft = msg.draft;
        break;
      case "SUBMIT": {
        const text = state.draft.trim();
        if (text === "" || conversation.inFlight) break;
        state.draft = "";
        conversation.send(text).then(undefined, (e: unknown) => {
          console.error(e);
        });
        break;
      }
      case "MODE_TOGGLED":
        state.mode = state.mode === "task" ? "learning" : "task";
        break;
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        state.activeMark = null;
        state.pending = null;
        break;
      case "MARK_CLICKED": {
        const mark = commits.find((c) => c.thread === msg.thread);
        if (!mark) break;
        state.anchor = null;
        state.activeMark = mark.thread;
        state.pending = mark.action;
        break;
      }
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(commits, anchor)) break;
            const thread = `t${commits.length + 1}` as ThreadId;
            commits.push({ thread, anchor, action: msg.msg.action });
            state.anchor = null;
            state.activeMark = thread;
            state.pending = msg.msg.action;
            state.query = "";
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
    }
    state.messages = conversation.messages;
    state.inFlight = conversation.inFlight;
  }

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    dispatching = false;
  }

  const view = new AppView(container, dispatch, state);

  conversation.onChange = () => {
    state.messages = conversation.messages;
    state.inFlight = conversation.inFlight;
    view.sync(state);
  };
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";
import { expect, type Page, test } from "@playwright/test";

function events(chunks: string[]): Anthropic.RawMessageStreamEvent[] {
  return [
    {
      type: "content_block_start",
      index: 0,
      content_block: { type: "text", text: "", citations: null },
    },
    ...chunks.map(
      (text): Anthropic.RawMessageStreamEvent => ({
        type: "content_block_delta",
        index: 0,
        delta: { type: "text_delta", text },
      }),
    ),
    { type: "content_block_stop", index: 0 },
    { type: "message_stop" } as Anthropic.RawMessageStreamEvent,
  ];
}

/** Stand in for the backend: replay `chunks` one delta at a time, and expose a
 * promise that resolves once the browser has sent its `start` frame. */
async function fakeBackend(page: Page, chunks: string[]) {
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const started: string[] = [];

  await page.routeWebSocket("**/api/socket", (ws) => {
    ws.onMessage(async (raw) => {
      const message = JSON.parse(String(raw)) as ClientMessage;
      started.push(JSON.stringify(message.params.messages));
      await gate;
      const send = (frame: ServerFrame) => ws.send(JSON.stringify(frame));
      for (const event of events(chunks)) {
        send({ type: "event", requestId: message.requestId, event });
      }
      send({ type: "done", requestId: message.requestId });
    });
  });

  return { release, started };
}

/** Selects characters [start, end) of message `msg` and lets the app capture
 * it, which it does on mouseup over the transcript. */
async function selectRange(
  page: Page,
  msg: number,
  start: number,
  end: number,
) {
  await page.evaluate(
    ({ msg, start, end }) => {
      const li = document.querySelectorAll("li")[msg];
      const root = li.lastElementChild as HTMLElement;
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let at = 0;
      let from: [Node, number] | null = null;
      let to: [Node, number] | null = null;
      let node = walker.nextNode();
      while (node) {
        const len = node.textContent?.length ?? 0;
        if (!from && start <= at + len) from = [node, start - at];
        if (!to && end <= at + len) to = [node, end - at];
        at += len;
        node = walker.nextNode();
      }
      if (!from || !to) throw new Error("range out of bounds");
      const range = document.createRange();
      range.setStart(from[0], from[1]);
      range.setEnd(to[0], to[1]);
      const selection = window.getSelection();
      selection?.removeAllRanges();
      selection?.addRange(range);
    },
    { msg, start, end },
  );
  await page.locator("ul").dispatchEvent("mouseup");
}

const SENTENCE = "the quick brown fox jumps over the lazy dog";

/** A transcript with one user message of known text, in learning mode. */
async function transcript(page: Page) {
  const backend = await fakeBackend(page, ["ok"]);
  backend.release();
  await page.goto("/");
  await page.getByRole("textbox").fill(SENTENCE);
  await page.getByRole("textbox").press("Enter");
  await expect(page.locator("li")).toHaveCount(2);
  await page.getByRole("button", { name: "Switch to learning mode" }).click();
}

test("streams a response into the transcript", async ({ page }) => {
  const backend = await fakeBackend(page, ["Hello", ", world"]);
  await page.goto("/");

  await page.getByRole("textbox").fill("hi");
  await page.getByRole("button", { name: "Send" }).click();

  await expect(page.locator('[data-role="user"]')).toHaveText(/hi/);
  backend.release();

  await expect(page.locator('[data-role="assistant"]')).toHaveText(
    /Hello, world/,
  );
  await expect(page.locator("li")).toHaveCount(2);
});

test("the composer is disabled while a turn is in flight", async ({ page }) => {
  const backend = await fakeBackend(page, ["ok"]);
  await page.goto("/");

  const input = page.getByRole("textbox");
  await input.fill("hi");
  await page.getByRole("button", { name: "Send" }).click();

  await expect(input).toBeDisabled();
  backend.release();
  await expect(input).toBeEnabled();
  await expect(input).toHaveValue("");
});

test("a second turn sends the full conversation", async ({ page }) => {
  const backend = await fakeBackend(page, ["ok"]);
  backend.release();
  await page.goto("/");

  const input = page.getByRole("textbox");
  await input.fill("first");
  await input.press("Enter");
  await expect(page.locator("li")).toHaveCount(2);

  await input.fill("second");
  await input.press("Enter");
  await expect(page.locator("li")).toHaveCount(4);

  expect(backend.started).toHaveLength(2);
  expect(JSON.parse(backend.started[1])).toHaveLength(3);
});

test("a live selection overlapping a mark offers no actions", async ({
  page,
}) => {
  await transcript(page);
  const explain = page.getByRole("button", {
    name: "I don't understand this.",
  });

  await selectRange(page, 0, 0, 9);
  await explain.click();
  await expect(page.locator("[data-mark]")).toHaveCount(1);

  await selectRange(page, 0, 4, 15);
  await expect(
    page.getByText("Select a non-overlapping section."),
  ).toBeVisible();
  await expect(explain).toBeHidden();

  await selectRange(page, 0, 10, 19);
  await expect(explain).toBeVisible();
});

test("two marks in one message are both clickable", async ({ page }) => {
  await transcript(page);
  const explain = page.getByRole("button", {
    name: "I don't understand this.",
  });
  const quote = page.locator("blockquote");

  await selectRange(page, 0, 0, 9);
  await explain.click();
  await selectRange(page, 0, 16, 19);
  await page.getByRole("button", { name: "Quiz me on this." }).click();

  const marks = page.locator("[data-mark]");
  await expect(marks).toHaveCount(2);
  await expect(marks.nth(0)).toHaveText("the quick");
  await expect(marks.nth(1)).toHaveText("fox");

  await marks.nth(0).click();
  await expect(quote).toHaveText("the quick");
  await marks.nth(1).click();
  await expect(quote).toHaveText("fox");
});

test("a new selection leaves committed marks rendered", async ({ page }) => {
  await transcript(page);
  await selectRange(page, 0, 0, 9);
  await page.getByRole("button", { name: "I don't understand this." }).click();

  await selectRange(page, 0, 20, 25);
  await expect(page.locator("[data-mark]")).toHaveCount(1);
  await expect(page.locator("[data-live]")).toHaveText("jumps");
});

---
name: vamp
description: Vamp frontend coding pattern. Use when writing or modifying frontend views, components, state management, or routing.
---

Vamp is a coding pattern — a repeating, predictable structure for organizing frontend code that is transparent, consistent and debuggable.

# Basic Example

A complete counter page showing all the parts:

```typescript
import { Binder, cls, mountStyle, ref, show, type View } from "./vamp.js";

// Start by defining the state machine, with explicit transitions.
interface State {
  count: number;
  loading: boolean;
}

type Msg =
  | { type: "INCREMENT" }
  | { type: "DECREMENT" }
  | { type: "SAVE"; count: number }
  | { type: "SAVE_DONE" }
  | { type: "SAVE_ERROR"; error: string };

// Mutate state and use inline effects
function update(state: State, msg: Msg, dispatch: (m: Msg) => void): void {
  switch (msg.type) {
    case "INCREMENT":
      state.count++;
      break;
    case "DECREMENT":
      state.count--;
      break;
    case "SAVE":
      state.loading = true;
      // use a linter to avoid floating promises.
      // do not use void saveCount to fix the lint. Instead, make it clear that we're handling success and failure.
      saveCount(msg.count).then(
        // async operations dispatch when they're done so views update
        () => dispatch({ type: "SAVE_DONE" }),
        (e) => dispatch({ type: "SAVE_ERROR", error: String(e) }),
      );

      break;
    case "SAVE_DONE":
      state.loading = false;
      break;
    case "SAVE_ERROR":
      state.loading = false;
      break;
  }
}

async function saveCount(count: number): Promise<void> {
  const count = await fetch("/api/count", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ count }),
  });
  return count;
}

// use the cls helper to define class selectors. This appends a short hash to the end of the class name to make it unique
// the counterClass variable handle allows you to find references, and prevents typos
const counterClass = cls("counter");

// mountStyle takes a css string and mounts it into the DOM as a <style> tag
mountStyle(`
.${counterClass} {
  display: flex;
  gap: 8px;
  align-items: center;
}
`);

// View is an interface defining sync and destroy. Implement this to be able to use views with Binder.
class CounterView implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State, Msg>;

  // constructor runs on mount. The container element is created by the parent
  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    // ref creates a unique identifier that we can use via the data-ref attribute to bind parts of the DOM.
    // it needs to be unique so that we don't accidentally select inside a child view when creating bindings.
    // ref returns `Ref` - a branded string type. Binding methods require Ref to force you to define data-refs this way.
    // define these in the constructor, so you don't reuse them between views & remounts.
    const countRef = ref("count");
    const incRef = ref("inc");
    const decRef = ref("dec");

    this.container = container;

    // NOTE! This only runs once on mount, so any view logic derived from state here will be static and will not update.
    // For elements that need to update, use the binder (see below).
    // sanitize html-escapes interpolated values to prevent XSS.
    container.innerHTML = sanitize`
      <!-- static values (cls, ref, initialState fields) can be interpolated directly into the template -->
      <div class="${counterClass}">
        <button data-ref="${decRef}">−</button>
        <span data-ref="${countRef}">0</span>
        <button data-ref="${incRef}">+</button>
      </div>
    `;

    this.b = new Binder(container, dispatch, initialState);

    // on destroy these elements will be removed from the DOM and these callbacks will be garbage collected
    this.b
      .ref(decRef)
      .addEventListener("click", () => dispatch({ type: "DECREMENT" }));
    this.b
      .ref(incRef)
      .addEventListener("click", () => dispatch({ type: "INCREMENT" }));

    // bindText uses textContent to prevent XSS
    // the binding will be evaluated with initial state here and re-evaluated every this.b.sync() with new state
    this.b.bindText(countRef, (s: State) => String(s.count));

    // bindStyle sets inline styles via a record. Clears removed properties between syncs.
    this.b.bindStyle(countRef, (s) =>
      s.loading ? { opacity: "0.5", "pointer-events": "none" } : {},
    );
  }

  sync(state: State): void {
    // you must explicitly call this.b.sync from the view's sync
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

function mountCounter(container: HTMLElement) {
  const state = { count: 0, loading: false };

  let dispatching = false;
  // the core event loop. User interacts with DOM -> dispatch a msg -> update the state -> sync the view
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg, dispatch);
    view.sync(state);
    dispatching = false;
  }

  const view = new CounterView(container, dispatch, state);
}
```

# Constructor renders structure, binder for dynamic state

The constructor runs **once on mount**, so you must use bindings to make views respond to state updates

```typescript
constructor(container, dispatch, initialState) {
  const r = initialState.response;
  const name = r.attendee ? displayName(r.attendee) : "(anonymous)";
  const buttons = r.attendee_id === null ? `<button>Match</button>` : "";
  // WRONG — name and buttons baked in at mount, never updated when state changes
  container.innerHTML = `<td>${name}${buttons}</td>`;
  this.b = new Binder(container, dispatch, initialState);
}
```

```typescript
constructor(container, dispatch, initialState) {
  const nameRef = ref("name");
  const matchBtnRef = ref("matchBtn");
  container.innerHTML = sanitize`
    <td>
      <span data-ref="${nameRef}"></span>
      <button data-ref="${matchBtnRef}" type="button">Match</button>
    </td>
  `;
  this.b = new Binder(container, dispatch, initialState);

  // RIGHT — bindings drive every state-derived bit
  this.b.bindText(nameRef, (s) =>
    s.response.attendee ? displayName(s.response.attendee) : "(anonymous)",
  );
  this.b.bindVisible(matchBtnRef, (s) => s.response.attendee_id === null);
}
```

# Prefer declarative DOM updates through bindings to imperative mutation

```typescript
sync(state: State): void {
  // WRONG — imperative mutation
  this.container.querySelector(".count")!.textContent = String(state.count);
  this.button.disabled = state.loading;
}
```

```typescript
// RIGHT — declare bindings once in the constructor; `sync()` uses binder
constructor() {
  this.b.bindText(countRef, (s) => String(s.count));
  this.b.bindDisabled(buttonRef, (s) => s.loading);
}

sync(state: State): void { this.b.sync(state); }
```

**Before writing any imperative DOM code in a view (`innerHTML =`, `appendChild`, `document.createElement`, property mutation in a render loop, or `${initialState.foo}` interpolation in a constructor template), stop and ask the user for explicit confirmation.**

```typescript
// WRONG — reaching for the DOM because no `bindX` exists for the property you need
this.checkboxEl.checked = state.value;
```

```typescript
// RIGHT — add the missing binding type to `vamp.ts`
this.b.bindChecked(checkboxRef, (s) => s.value);
```

# `bindSlot` — mount/unmount child views

```typescript
// The child view exports its own messages and update function:
import { type Msg as NavMsg, update as navUpdate } from "./nav.js";

// The parent wraps them into its own message type:
type Msg =
  | { type: "NAV_MSG"; msg: NavMsg }
  | { type: "OTHER_STUFF" };

// The parent's update delegates to the child's update:
function update(state: State, msg: Msg, dispatch: (m: Msg) => void): void {
  switch (msg.type) {
    case "NAV_MSG":
      navUpdate(state, msg.msg, (msg: NavMsg) => dispatch({type: "NAV_MSG", msg}));
      break;
  }
}

constructor(container: HTMLElement, dispatch: (msg: Msg) => void, initialState: State) {
  const navRef = ref("nav");
  const contentRef = ref("content");
  const pageRef = ref("page");

  container.innerHTML = sanitize`
    <div data-ref="${navRef}"></div>
    <div data-ref="${contentRef}"></div>
    <div data-ref="${pageRef}"></div>
  `;
  this.b = new Binder(container, dispatch, initialState);

  // show() returns a SlotContent, which contains the ViewClass and State that should render in the slot
  // This is a managed effect. When the ViewClass changes, we unmount the old one and mount the new one.
  // When the ViewClass is the same, we sync it to the new state.
  this.b.bindSlot(navRef, (s) => show(NavView, {
    loggedIn: s.auth.status === "logged in",
    displayName: s.displayName,
    email: s.email,
  // Optional last arg to show() is the dispatch method that's passed to the child. This can wrap child messages into
  // parent messages
  }, (navMsg) => ({ type: "NAV_MSG", msg: navMsg })));

  this.b.bindSlot(contentRef, (s) => {
    // when the bindSlot binding evaluates to undefined, the child is unmounted
    if (!s.selectedId) return undefined;
    return show(DetailView, { id: s.selectedId }, (m) => ({ type: "DETAIL_MSG", msg: m }));
  });

  // switch pattern
  this.b.bindSlot(pageRef, (s) => {
    switch (s.load.status) {
      case "loading":
        // When we return the same class constructor, we call sync on the existing instance
        // otherwise we unmount the previous view, and mount the new one
        return show(SpinnerView, {});
      case "loaded":
        return show(ListView, { items: s.load.items });
      case "error":
        return show(ErrorView, { message: s.load.message });
    }
  });
}
```

## Don't manually mount/unmount child views

```typescript
// WRONG — managing the child lifecycle by hand
sync(state: State): void {
  if (state.selectedId && !this.detail) {
    this.detail = new DetailView(this.detailContainer, dispatch, { id: state.selectedId });
  } else if (!state.selectedId && this.detail) {
    this.detail.destroy();
    this.detail = null;
  } else if (this.detail) {
    this.detail.sync({ id: state.selectedId });
  }
}

constructor() {
  // RIGHT — `bindSlot` does mount/sync/unmount automatically based on the returned `show()`:
  this.b.bindSlot(detailRef, (s) =>
    s.selectedId ? show(DetailView, { id: s.selectedId }) : undefined,
  );
}
```

## Wrapper views — pass dynamic children as `SlotContent` props

A wrapper view (modal, popover, card shell, …) renders its own chrome and mounts
caller-supplied content into a slot. The content is passed in as a `SlotContent`
**prop** (the result of `show()`), and the wrapper forwards it through its own
`bindSlot`:

```typescript
// Wrapper: chrome + a slot the caller fills. Its own Msg is usually `never` —
// the wrapped child's messages flow through the dispatch baked into the SlotContent.
class ModalView implements View<{ content: SlotContent; onClose: () => void }, never> {
  constructor(container, _dispatch, initialState) {
    // ...renders overlay/panel/close button + a data-ref="content" placeholder...
    this.b.bindSlot(contentRef, (s) => s.content);
  }
}
```

`SlotContent` is not a live view — it's an inert descriptor (which view + what
state + which dispatch) that the slot diffs (mount / sync / remount). This is the
"children as data" model.

**Build the child `show()` inside the parent's `bindSlot` callback, not in the
constructor.** Because the parent wraps the wrapper in its own `bindSlot`, the
child descriptor is recomputed from the latest state on every sync — so the child
syncs with fresh state:

```typescript
// RIGHT — child show() is created inside the parent's bindSlot callback, so it's
// rebuilt from the latest state each sync.
this.b.bindSlot(modalRef, (s) => {
  if (!s.authModalOpen) return undefined;
  return show(
    ModalView,
    {
      content: show(AuthFormView, authFormState({ email: s.email }), {}, noop),
      onClose: () => dispatch({ type: "CLOSE_AUTH" }),
    },
    {},
    noop,
  );
});
```

```typescript
// WRONG — content show() captured once in the constructor; it freezes the state
// it closed over and never reflects later updates.
const content = show(AuthFormView, authFormState({ email: this.email }), {}, noop);
this.b.bindSlot(modalRef, (s) =>
  s.authModalOpen ? show(ModalView, { content, onClose }, {}, noop) : undefined,
);
```

Prefer the `SlotContent` value over a thunk (`() => SlotContent`) or render-prop
(`(api) => SlotContent`). The value matches this idiom and gets freshness for
free from the dispatch loop. Reach for a render-prop only when the wrapper must
inject its own state/callbacks into the content (e.g. a `close` handle) and a
message back-channel would be clumsier; a thunk only pays off for expensive,
normally-hidden content you want to skip building.

## `bindList` — keyed list of child views

```typescript
constructor(container: HTMLElement, dispatch: (msg: Msg) => void, initialState: State) {
  const listRef = ref("list");

  container.innerHTML = sanitize`<ul data-ref="${listRef}"></ul>`;
  this.b = new Binder(container, dispatch, initialState);

  // "li" is the wrapper tag created for each child, and passed to ItemView as the container element
  this.b.bindList(listRef, "li", (s) =>
    s.items.map((item) =>
      // showKeyed is like show, but uses the key to distinguish element identity instead of the view class
      // keys must be unique
      showKeyed(item.id, ItemView, {
        item,
        isSelected: item.id === s.selectedId,
      // optional last argument to wire up actions for this element of the list.
      }, (msg: ItemMsg) => dispatch({type: 'ITEM_MSG', itemId: item.id, msg})),
    ),
  );

  // On each sync:
  // 1. New keys → mount new views
  // 2. Existing keys → sync with new state if the view constructor is the same (reuse by key), otherwise remount
  // 3. Removed keys → destroy and remove from DOM
  // 4. Reorder DOM to match array order
}
```

```typescript
this.b.bindList(listRef, "li", (s) =>
  // WRONG — keying by array index. Use stable identifiers!
  s.items.map((item, i) => showKeyed(String(i), ItemView, { item })),
);
```

```typescript
this.b.bindList(listRef, "li", (s) =>
  // RIGHT — key by the stable id of the item, so reorders move existing DOM nodes instead of updating them with new state
  s.items.map((item) => showKeyed(item.id, ItemView, { item })),
);
```

# Context and stores (dependency injection)

Stores hold shared state that outlives any individual view. Context (`ctx`) is the bag of dependencies — stores, API clients, anything else that has a lifecycle that is different from when a view is mounted/unmounted.

- **Created at the root, threaded down.** The app's `ctx` is built once in `main.ts` and passed as a constructor arg to the root view. Each parent picks the subset of its own ctx to hand to each child at the `show()` / `showKeyed()` call site.
- **Each view declares only the slice it uses.** A view's `Ctx` generic is an inline structural type listing the exact fields it touches. This is useful for unit testing - we only need to mock the context that the view actually uses.
- **Stores wire into the same dispatch loop as views.** A store exposes a `Msg` type and a `update(msg)` reducer. The root is responsible for passing dispatches back into the store's update function.
- **The Binder is ctx-agnostic.** If a view needs ctx for its own logic, capture it as a private field in the constructor; the Binder does not thread ctx.

```typescript
// Root: build ctx + stores once. Store dispatches re-enter the root loop.
class EventStore {
  constructor(private api: Api, private dispatch: (m: EventStoreMsg) => void) {}
  update(msg: EventStoreMsg): void {}
  loadUngrouped(orgId: OrgId): void {
    this.dispatch({ type: "LOAD_START", orgId });
    this.api(...).then((p) => this.dispatch({ type: "LOAD_OK", orgId, page: p }));
  }
}

type MainMsg =
  | { type: "NAVIGATE"; route: Route }
  | { type: "EVENT_STORE_MSG"; msg: EventStoreMsg };

type AppCtx = { eventStore: EventStore };

function createAppCtx(dispatch: (m: MainMsg) => void): AppCtx {
  return {
    eventStore: new EventStore(api, (msg) =>
      dispatch({ type: "EVENT_STORE_MSG", msg }),
    ),
  };
}

function update(state: MainState, msg: MainMsg, ctx: AppCtx): void {
  switch (msg.type) {
    case "EVENT_STORE_MSG":
      ctx.eventStore.update(msg.msg);
      break;
    // ...
  }
}

// Child view: declares the exact slice of ctx it needs.
type EventsCtx = { eventStore: EventStore };

class EventsListPage implements View<EventsState, EventsMsg, EventsCtx> {
  constructor(
    container: HTMLElement,
    dispatch: (m: EventsMsg) => void,
    initialState: EventsState,
    private ctx: EventsCtx,
  ) {
    // ...
  }
}

// Parent: passes its own (wider) ctx; structural typing narrows it for the child.
this.b.bindSlot(pageRef, (s) =>
  show(EventsListPage, eventsState(s.orgId), this.ctx, noop),
);
```

This is dependency injection in its simplest, most explicit form: dependencies travel as plain constructor arguments, the type system documents and enforces the per-view contract, and there is no hidden global state to mock or reset between tests.

## Store <-> View contract

A store method that triggers an async operation (network call, IO) can dispatch its own internal messages internally so every view subscribed via `getState()` re-renders. But the calling view also gets the same promise back and is expected to attach its own handlers.

```typescript
case "DELETE_GROUP": {
  ctx.eventGroupStore
    .deleteGroup(msg.id, state.orgId)
    // explicit error handling. Enforced by no-floating-promises lint rule
    .then(undefined, (e) =>
      dispatch({ type: "ERROR", message: String(e) }),
    );
  break;
}
```

Two things are happening here, and both matter:

1. **The store updates global state.** `deleteGroup` removes the group from its internal map and dispatches a store msg; every view reading `eventGroupStore.getState(...)` re-renders on the next sync.
2. **The view dispatches its own actions.** Only this view knows whether to surface the error in _its_ error banner, clear a local form field on success, close a modal, advance a wizard step, etc. Those are view-local concerns the store can't know about.

This pattern also pairs with the no-floating-promises lint: every store call has a visible `.then(success, failure)` at the call site, so a forgotten error branch is a lint error rather than a silently-swallowed rejection. Do not use `void store.method()` to silence the lint — handle both branches explicitly even if one is a no-op (`.then(undefined, handleErr)` is fine).

Rule of thumb: **the store owns the data; the view owns its own UI reaction to the operation.** Don't move view-local concerns (form resets, error banners, navigation) into the store, and don't drop the promise on the floor assuming the store's internal dispatches are enough.

## Read live ctx state inside binding callbacks, not in the constructor

Binding callbacks (`bindSlot`, `bindText`, `bindList`, …) run on every `sync()`. Code in the constructor body runs **once on mount**. If you read ctx/store state outside a binding callback and close over it, the value freezes at mount time and never updates — even though the store keeps changing.

```typescript
constructor(container, dispatch, initialState, private ctx: Ctx) {
  // WRONG — read once at mount, captured by the closure, never refreshed
  const prop = this.ctx.store.getProp();
  this.b.bindSlot(slotRef, (s) => show(ChildView, { s, prop }));
}
```

```typescript
constructor(container, dispatch, initialState, private ctx: Ctx) {
  // RIGHT — re-read on every sync, so store updates flow through
  this.b.bindSlot(slotRef, (s) => {
    const prop = this.ctx.store.getProp();
    return show(ChildView, { s, prop });
  });
}
```

Rule: anything that can change after mount — including derived values pulled from ctx/stores — must be computed **inside** the binding callback. The constructor is for static structure and one-time wiring only.

# Routing

The URL bar is just another input — like a button or a text field. The same unidirectional cycle applies: listen for events (popstate, link clicks), dispatch a `NAVIGATE` message, update state, sync the view. Views use plain `<a href="...">` elements for navigation, so middle-click / ctrl-click to open in a new tab work natively; a delegated click listener intercepts normal left-clicks for SPA navigation.

The router itself is split into a **controller** and a **view**, mirroring the rest of the app (state-owner vs DOM-half):

**`RouterController`** lives in the app context (`ctx.router`) and owns the canonical `route` state plus the pending address-bar write intent. It is mutated only from reducers via `update(msg)`, touches no DOM, and resolves auth redirects centrally (anonymous → `login`, signed-in → away from `login`, always as a `replace`).

It exposes an `epoch` counter, bumped on every route change, and `desired()` returning `{ path, kind }` (`kind` is `"push"` | `"replace"`). The path is derived from the route via `routeToPath`, so the view never re-derives routing rules.

**`RouterView`** is the address bar's view half. It registers the input listeners on `mount()` (popstate + delegated link clicks) and reconciles `history.*` during `sync()`, called by the root dispatch loop after the DOM renders:

```typescript
function dispatch(msg: MainMsg): void {
  // ...
  update(state, msg, ctx, dispatch);
  view.sync(state);
  routerView.sync(); // write any URL change the controller requested
  ctx.postRenderBus.flush();
}
```

`sync()` is gated on the controller's `epoch`: the view records the last epoch it reconciled and no-ops while they match, so a sync triggered by unrelated state changes (or a user editing the address bar) never re-writes the URL — only a genuine route change does. It is also idempotent against the current location (when `desired().path` already equals the address bar, e.g. a popstate the browser already applied, nothing is written), keeping back/forward clean.

Browser-driven navigation flows the other way: `RouterView` listens for `popstate` and link clicks, and dispatches `{ type: "NAVIGATE", route: currentRoute()/parseRoute(...) }`. The view emits only a `RouterMsg` (`NAVIGATE` with an optional `kind`); the root loop wraps it into the app-wide message, keeping the router decoupled from the app message type. Same-page link clicks (path+search unchanged) skip dispatch and just `pushState` for the hash.

Note: `history.pushState()` does _not_ fire a `popstate` event, so there is no double-dispatch. `popstate` only fires on back/forward navigation.

# Post-render events

Reducers must never touch the DOM, and views must never run imperative DOM work inside `sync()`. But some work — scroll, focus, measurement — _has_ to happen after the DOM reflects the new state, and it belongs in the view that owns the relevant container/refs. The **post-render event bus** bridges these two phases.

`PostRenderEventBus<Event>` (in `vamp.ts`) is a tiny framework object, generic over an app-supplied event union, with three methods:

- `emit(event)` — queue an event during a dispatch. Called from the **reducer side** (`update` / root message handlers).
- `subscribe(handler): () => void` — register a listener. Called by a **view** (usually in its constructor); returns an unsubscribe function to call in `destroy()`.
- `flush()` — deliver every queued event to the current subscribers, then clear the queue. Called by the **root loop**, once, right after the view has synced.

The bus lives on `AppCtx` (`ctx.postRenderBus`), created once at the root and threaded down like any other store. The event union is an app-level discriminated union (e.g. `PostRenderEvent` in `app-ctx.ts`); subscribers `switch` on `event.type` and ignore events they don't care about.

```typescript
// Root dispatch loop: flush after sync, so the DOM is up to date.
function dispatch(msg: MainMsg): void {
  update(state, msg, ctx, dispatch); // reducers may ctx.postRenderBus.emit(event)
  view.sync(state); // DOM now reflects the new state
  ctx.postRenderBus.flush(); // deliver queued events -> subscribers do DOM work
}
```

```typescript
// Reducer side: emit in response to an action (never touch the DOM here).
case "SEARCH_STORE_MSG":
  ctx.searchStore.update(msg.msg);
  if (msg.msg.type === "OK" && state.pageState.page === "calendar")
    ctx.postRenderBus.emit({ type: "calendar:scroll-to-first" });
  break;
```

```typescript
// View side: subscribe in the constructor, unsubscribe in destroy.
constructor(container, dispatch, initialState, private ctx: Ctx) {
  // ...
  this.unsubscribe = this.ctx.postRenderBus.subscribe((event) => {
    if (event.type === "calendar:scroll-to-first") this.scrollToFirstEvent();
  });
}

destroy(): void {
  this.unsubscribe();
  // ...
}
```

Events are delivered to _currently mounted_ subscribers only. A view that just unmounted won't receive anything; a view that mounted during the same dispatch's `sync` is already subscribed (it subscribes in its constructor), so it receives events emitted in that same dispatch.

## Invariants

- Reducers never touch the DOM; all DOM work happens in subscribers during `flush()`, after `sync()`.
- `flush()` runs exactly once per dispatch and clears the queue, so an event is delivered at most once.
- Subscriptions are torn down in `destroy()` — the bus must hold no reference to an unmounted view.
- The dispatch re-entrancy guard still holds: `emit` only queues; subscribers run during `flush`, outside `update`, and must not synchronously re-dispatch (schedule via rAF if they must).

